-- writing_expression에 표현의 난이도이자 노출 하한선인 difficulty_level을 추가한다.
-- user_profile.learning_level과 같은 1~5 척도를 쓴다.
-- 노출 규칙: 수준 1~3 유저에게는 difficulty_level 1~3만, 수준 4~5 유저에게는 1~5 전부를 보여준다.

ALTER TABLE writing_expression
    ADD COLUMN difficulty_level INTEGER;

